// Fictional, local Messages examples. These are editable authored drafts, not
// admitted Originals, signatures, invoices sent to a client or payment results.
const resource=(slug,label,kind='templates')=>({label,href:`/learn/${kind==='guides'?'resources':kind}/${slug}/`});
const scenario=input=>{
 const proposal={kind:'proposal',title:input.project,summary:input.summary,items:input.items.map(([description,unitPriceUsdCents,quantity='1'])=>({description,quantity,unitPriceUsdCents})),deliverables:input.deliverables,timeline:input.timeline,terms:input.terms};
 return {
  id:input.id,title:input.title,owner:input.owner,client:input.client,brief:input.brief,
  suggestedReply:input.reply,scriptedTwinReply:input.twin,
  proposal,
  invoice:{...proposal,kind:'invoice',title:input.invoiceTitle??`${input.project} — invoice draft`,summary:input.invoiceSummary??`Draft request for the work described below. ${input.invoiceNote}`,terms:`${input.invoiceNote} This local example has no recorded payment or sent invoice. Confirm the final amount, recipient, due date and any applicable tax before issuing.`},
  document:{kind:'document',title:input.documentTitle,summary:input.documentSummary,sections:input.sections.map(([heading,body])=>({heading,body})),tables:[{title:'Working review checklist',columns:['Checkpoint','Responsible person','What to confirm'],rows:input.checkpoints}]},
  agreement:{kind:'agreement',title:`${input.project} — working agreement`,summary:`Fictional working terms between ${input.owner.name} and ${input.client.name}${input.client.company?' at '+input.client.company:''}. Edit and review the exact version before using it. This example is unsigned.`,sections:input.agreementSections.map(([heading,body])=>({heading,body})),tables:[]},
  delivery:{title:input.delivery[0],body:input.delivery[1]},followup:{title:input.followup[0],body:input.followup[1]},resources:input.resources,
 };
};

